#include <bits/stdc++.h>
using namespace std;

// Strings are kept as Unicode code points; lone surrogates from unicode escapes stay as they are.
typedef vector<uint32_t> Str;

struct Node {
    char type;                        // o(bject) a(rray) s(tring) n(umber) t(rue) f(alse) z(null)
    Str text;                         // string value
    string number;                    // canonical decimal text
    vector<pair<Str, int>> members;   // object members -> node index
    vector<int> items;                // array items -> node index
};

string in;
size_t p = 0;
vector<Node> nodes;

void skipSpace() {
    while (p < in.size() && (in[p] == ' ' || in[p] == '\t' || in[p] == '\n' || in[p] == '\r')) p++;
}

uint32_t hex4() {
    uint32_t v = 0;
    for (int i = 0; i < 4; i++) {
        char c = in[p++];
        v = v * 16 + (isdigit((unsigned char)c) ? c - '0' : tolower(c) - 'a' + 10);
    }
    return v;
}

Str parseString() {
    Str s;
    p++;  // opening quote
    while (in[p] != '"') {
        unsigned char c = in[p];
        if (c == '\\') {
            char e = in[p + 1];
            p += 2;
            if (e == 'b') s.push_back(8);
            else if (e == 'f') s.push_back(12);
            else if (e == 'n') s.push_back(10);
            else if (e == 'r') s.push_back(13);
            else if (e == 't') s.push_back(9);
            else if (e == 'u') {
                uint32_t u = hex4();
                // A high surrogate followed by a low one is a single code point.
                if (u >= 0xD800 && u <= 0xDBFF && in.compare(p, 2, "\\u") == 0) {
                    size_t save = p;
                    p += 2;
                    uint32_t low = hex4();
                    if (low >= 0xDC00 && low <= 0xDFFF) u = 0x10000 + ((u - 0xD800) << 10) + (low - 0xDC00);
                    else p = save;
                }
                s.push_back(u);
            } else s.push_back((unsigned char)e);  // \" \\ \/
        } else {
            // UTF-8 decode.
            int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
            uint32_t cp = extra == 0 ? c : extra == 1 ? c & 0x1F : extra == 2 ? c & 0x0F : c & 0x07;
            for (int i = 1; i <= extra; i++) cp = (cp << 6) | (in[p + i] & 0x3F);
            s.push_back(cp);
            p += extra + 1;
        }
    }
    p++;  // closing quote
    return s;
}

// Exact decimal value of the token without exponent, redundant zeros or a negative zero.
string parseNumber() {
    bool negative = in[p] == '-';
    if (negative) p++;
    string digits;
    long long exponent = 0;
    while (p < in.size() && isdigit((unsigned char)in[p])) digits += in[p++];
    if (p < in.size() && in[p] == '.') {
        p++;
        while (p < in.size() && isdigit((unsigned char)in[p])) {
            digits += in[p++];
            exponent--;
        }
    }
    if (p < in.size() && (in[p] == 'e' || in[p] == 'E')) {
        p++;
        int sign = 1;
        if (in[p] == '+') p++;
        else if (in[p] == '-') {
            sign = -1;
            p++;
        }
        long long e = 0;
        while (p < in.size() && isdigit((unsigned char)in[p])) e = e * 10 + (in[p++] - '0');
        exponent += sign * e;
    }
    // value = digits * 10^exponent
    size_t first = digits.find_first_not_of('0');
    if (first == string::npos) return "0";
    digits = digits.substr(first);
    while (digits.back() == '0') {
        digits.pop_back();
        exponent++;
    }
    string text;
    if (exponent >= 0) text = digits + string(exponent, '0');
    else if ((long long)digits.size() > -exponent)
        text = digits.substr(0, digits.size() + exponent) + "." + digits.substr(digits.size() + exponent);
    else text = "0." + string(-exponent - digits.size(), '0') + digits;
    return (negative ? "-" : "") + text;
}

int parseValue() {
    skipSpace();
    int id = nodes.size();
    nodes.push_back(Node());
    char c = in[p];
    if (c == '{') {
        nodes[id].type = 'o';
        p++;
        skipSpace();
        if (in[p] == '}') p++;
        else
            while (true) {
                skipSpace();
                Str key = parseString();
                skipSpace();
                p++;  // ':'
                int child = parseValue();
                nodes[id].members.push_back({key, child});
                skipSpace();
                if (in[p++] == '}') break;  // otherwise ','
            }
    } else if (c == '[') {
        nodes[id].type = 'a';
        p++;
        skipSpace();
        if (in[p] == ']') p++;
        else
            while (true) {
                int child = parseValue();
                nodes[id].items.push_back(child);
                skipSpace();
                if (in[p++] == ']') break;
            }
    } else if (c == '"') {
        nodes[id].type = 's';
        Str s = parseString();
        nodes[id].text = s;
    } else if (c == 't') {
        nodes[id].type = 't';
        p += 4;
    } else if (c == 'f') {
        nodes[id].type = 'f';
        p += 5;
    } else if (c == 'n') {
        nodes[id].type = 'z';
        p += 4;
    } else {
        nodes[id].type = 'n';
        string number = parseNumber();
        nodes[id].number = number;
    }
    return id;
}

void hexEscape(uint32_t c, string &out) {
    char buf[8];
    snprintf(buf, sizeof buf, "\\u%04x", c);
    out += buf;
}

// Same escaping as Python json.dumps(..., ensure_ascii=True).
void encodeString(const Str &s, string &out) {
    out += '"';
    for (uint32_t c : s) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else if (c == 8) out += "\\b";
        else if (c == 12) out += "\\f";
        else if (c >= 0x20 && c <= 0x7E) out += (char)c;
        else if (c > 0xFFFF) {
            hexEscape(0xD800 + ((c - 0x10000) >> 10), out);
            hexEscape(0xDC00 + ((c - 0x10000) & 0x3FF), out);
        } else hexEscape(c, out);
    }
    out += '"';
}

void encode(int id, string &out) {
    const Node &v = nodes[id];
    if (v.type == 'z') out += "null";
    else if (v.type == 't') out += "true";
    else if (v.type == 'f') out += "false";
    else if (v.type == 'n') out += v.number;
    else if (v.type == 's') encodeString(v.text, out);
    else if (v.type == 'a') {
        out += '[';
        for (size_t i = 0; i < v.items.size(); i++) {
            if (i) out += ',';
            encode(v.items[i], out);
        }
        out += ']';
    } else {
        // Keys in ascending code point order.
        vector<pair<Str, int>> members = v.members;
        sort(members.begin(), members.end());
        out += '{';
        for (size_t i = 0; i < members.size(); i++) {
            if (i) out += ',';
            encodeString(members[i].first, out);
            out += ':';
            encode(members[i].second, out);
        }
        out += '}';
    }
}

int main() {
    in.assign(istreambuf_iterator<char>(cin), istreambuf_iterator<char>());
    int root = parseValue();
    skipSpace();
    Str path = parseString();
    // Split the path on '.', keeping empty segments, and walk object keys only.
    vector<Str> keys(1);
    for (uint32_t c : path) {
        if (c == '.') keys.push_back(Str());
        else keys.back().push_back(c);
    }
    int cur = root;
    for (const Str &key : keys) {
        int next = -1;
        if (nodes[cur].type == 'o')
            for (auto &[k, child] : nodes[cur].members)
                if (k == key) {
                    next = child;
                    break;
                }
        if (next < 0) {
            cur = -1;
            break;
        }
        cur = next;
    }
    string out;
    if (cur < 0) out = "null";
    else encode(cur, out);
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    // Strings are kept as Unicode code points; lone surrogates from unicode escapes stay as they are.
    static final class Node {
        char type; // o(bject) a(rray) s(tring) n(umber) t(rue) f(alse) z(null)
        int[] text;
        String number;
        List<int[]> keys = new ArrayList<>();
        List<Node> values = new ArrayList<>();
    }

    static byte[] in;
    static int p = 0;

    static void skipSpace() {
        while (p < in.length && (in[p] == ' ' || in[p] == '\t' || in[p] == '\n' || in[p] == '\r')) p++;
    }

    static int hex4() {
        int v = 0;
        for (int i = 0; i < 4; i++) v = v * 16 + Character.digit(in[p++], 16);
        return v;
    }

    static int[] parseString() {
        int[] s = new int[16];
        int n = 0;
        p++; // opening quote
        while (in[p] != '"') {
            int c = in[p] & 0xFF, cp;
            if (c == '\\') {
                int e = in[p + 1];
                p += 2;
                if (e == 'b') cp = 8;
                else if (e == 'f') cp = 12;
                else if (e == 'n') cp = 10;
                else if (e == 'r') cp = 13;
                else if (e == 't') cp = 9;
                else if (e == 'u') {
                    cp = hex4();
                    // A high surrogate followed by a low one is a single code point.
                    if (cp >= 0xD800 && cp <= 0xDBFF && p + 1 < in.length && in[p] == '\\' && in[p + 1] == 'u') {
                        int save = p;
                        p += 2;
                        int low = hex4();
                        if (low >= 0xDC00 && low <= 0xDFFF) cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                        else p = save;
                    }
                } else cp = e; // \" \\ \/
            } else {
                // UTF-8 decode.
                int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
                cp = extra == 0 ? c : extra == 1 ? c & 0x1F : extra == 2 ? c & 0x0F : c & 0x07;
                for (int i = 1; i <= extra; i++) cp = (cp << 6) | (in[p + i] & 0x3F);
                p += extra + 1;
            }
            if (n == s.length) s = Arrays.copyOf(s, n * 2);
            s[n++] = cp;
        }
        p++; // closing quote
        return Arrays.copyOf(s, n);
    }

    static boolean isDigit(int i) {
        return i < in.length && in[i] >= '0' && in[i] <= '9';
    }

    // Exact decimal value of the token without exponent, redundant zeros or a negative zero.
    static String parseNumber() {
        boolean negative = in[p] == '-';
        if (negative) p++;
        StringBuilder digits = new StringBuilder();
        long exponent = 0;
        while (isDigit(p)) digits.append((char) in[p++]);
        if (p < in.length && in[p] == '.') {
            p++;
            while (isDigit(p)) {
                digits.append((char) in[p++]);
                exponent--;
            }
        }
        if (p < in.length && (in[p] == 'e' || in[p] == 'E')) {
            p++;
            int sign = 1;
            if (in[p] == '+') p++;
            else if (in[p] == '-') {
                sign = -1;
                p++;
            }
            long e = 0;
            while (isDigit(p)) e = e * 10 + (in[p++] - '0');
            exponent += sign * e;
        }
        // value = digits * 10^exponent
        String d = digits.toString().replaceFirst("^0+", "");
        if (d.isEmpty()) return "0";
        int end = d.length();
        while (d.charAt(end - 1) == '0') {
            end--;
            exponent++;
        }
        d = d.substring(0, end);
        String text;
        if (exponent >= 0) text = d + "0".repeat((int) exponent);
        else if (d.length() > -exponent) {
            int point = (int) (d.length() + exponent);
            text = d.substring(0, point) + "." + d.substring(point);
        } else text = "0." + "0".repeat((int) (-exponent - d.length())) + d;
        return (negative ? "-" : "") + text;
    }

    static Node parseValue() {
        skipSpace();
        Node node = new Node();
        int c = in[p];
        if (c == '{') {
            node.type = 'o';
            p++;
            skipSpace();
            if (in[p] == '}') p++;
            else
                while (true) {
                    skipSpace();
                    node.keys.add(parseString());
                    skipSpace();
                    p++; // ':'
                    node.values.add(parseValue());
                    skipSpace();
                    if (in[p++] == '}') break; // otherwise ','
                }
        } else if (c == '[') {
            node.type = 'a';
            p++;
            skipSpace();
            if (in[p] == ']') p++;
            else
                while (true) {
                    node.values.add(parseValue());
                    skipSpace();
                    if (in[p++] == ']') break;
                }
        } else if (c == '"') {
            node.type = 's';
            node.text = parseString();
        } else if (c == 't') {
            node.type = 't';
            p += 4;
        } else if (c == 'f') {
            node.type = 'f';
            p += 5;
        } else if (c == 'n') {
            node.type = 'z';
            p += 4;
        } else {
            node.type = 'n';
            node.number = parseNumber();
        }
        return node;
    }

    static void hexEscape(int c, StringBuilder out) {
        out.append(String.format("\\u%04x", c));
    }

    // Same escaping as Python json.dumps(..., ensure_ascii=True).
    static void encodeString(int[] s, StringBuilder out) {
        out.append('"');
        for (int c : s) {
            if (c == '"') out.append("\\\"");
            else if (c == '\\') out.append("\\\\");
            else if (c == '\n') out.append("\\n");
            else if (c == '\r') out.append("\\r");
            else if (c == '\t') out.append("\\t");
            else if (c == 8) out.append("\\b");
            else if (c == 12) out.append("\\f");
            else if (c >= 0x20 && c <= 0x7E) out.append((char) c);
            else if (c > 0xFFFF) {
                hexEscape(0xD800 + ((c - 0x10000) >> 10), out);
                hexEscape(0xDC00 + ((c - 0x10000) & 0x3FF), out);
            } else hexEscape(c, out);
        }
        out.append('"');
    }

    static void encode(Node v, StringBuilder out) {
        switch (v.type) {
            case 'z' -> out.append("null");
            case 't' -> out.append("true");
            case 'f' -> out.append("false");
            case 'n' -> out.append(v.number);
            case 's' -> encodeString(v.text, out);
            case 'a' -> {
                out.append('[');
                for (int i = 0; i < v.values.size(); i++) {
                    if (i > 0) out.append(',');
                    encode(v.values.get(i), out);
                }
                out.append(']');
            }
            default -> {
                // Keys in ascending code point order.
                Integer[] order = new Integer[v.keys.size()];
                for (int i = 0; i < order.length; i++) order[i] = i;
                Arrays.sort(order, (a, b) -> Arrays.compare(v.keys.get(a), v.keys.get(b)));
                out.append('{');
                for (int i = 0; i < order.length; i++) {
                    if (i > 0) out.append(',');
                    encodeString(v.keys.get(order[i]), out);
                    out.append(':');
                    encode(v.values.get(order[i]), out);
                }
                out.append('}');
            }
        }
    }

    public static void main(String[] args) throws IOException {
        in = System.in.readAllBytes();
        Node cur = parseValue();
        skipSpace();
        int[] path = parseString();
        // Split the path on '.', keeping empty segments, and walk object keys only.
        int start = 0;
        for (int i = 0; i <= path.length && cur != null; i++) {
            if (i < path.length && path[i] != '.') continue;
            int[] key = Arrays.copyOfRange(path, start, i);
            start = i + 1;
            Node next = null;
            if (cur.type == 'o')
                for (int j = 0; j < cur.keys.size(); j++)
                    if (Arrays.equals(cur.keys.get(j), key)) {
                        next = cur.values.get(j);
                        break;
                    }
            cur = next;
        }
        StringBuilder out = new StringBuilder();
        if (cur == null) out.append("null");
        else encode(cur, out);
        out.append('\n');
        PrintStream ps = new PrintStream(new FileOutputStream(FileDescriptor.out), true, "US-ASCII");
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
	"strings"
)

// node holds a JSON value; strings are code points, lone surrogates from unicode escapes kept as they are.
type node struct {
	kind   byte // o(bject) a(rray) s(tring) n(umber) t(rue) f(alse) z(null)
	text   []rune
	number string
	keys   [][]rune
	values []*node
}

var in []byte
var p int

func skipSpace() {
	for p < len(in) && (in[p] == ' ' || in[p] == '\t' || in[p] == '\n' || in[p] == '\r') {
		p++
	}
}

func hex4() rune {
	v := rune(0)
	for i := 0; i < 4; i++ {
		c := in[p]
		p++
		switch {
		case c >= '0' && c <= '9':
			v = v*16 + rune(c-'0')
		case c >= 'a' && c <= 'f':
			v = v*16 + rune(c-'a'+10)
		default:
			v = v*16 + rune(c-'A'+10)
		}
	}
	return v
}

func parseString() []rune {
	s := []rune{}
	p++ // opening quote
	for in[p] != '"' {
		c := in[p]
		var cp rune
		if c == '\\' {
			e := in[p+1]
			p += 2
			switch e {
			case 'b':
				cp = 8
			case 'f':
				cp = 12
			case 'n':
				cp = 10
			case 'r':
				cp = 13
			case 't':
				cp = 9
			case 'u':
				cp = hex4()
				// A high surrogate followed by a low one is a single code point.
				if cp >= 0xD800 && cp <= 0xDBFF && p+1 < len(in) && in[p] == '\\' && in[p+1] == 'u' {
					save := p
					p += 2
					low := hex4()
					if low >= 0xDC00 && low <= 0xDFFF {
						cp = 0x10000 + (cp-0xD800)<<10 + (low - 0xDC00)
					} else {
						p = save
					}
				}
			default: // \" \\ \/
				cp = rune(e)
			}
		} else {
			// UTF-8 decode.
			extra := 0
			switch {
			case c < 0x80:
				cp = rune(c)
			case c < 0xE0:
				extra, cp = 1, rune(c&0x1F)
			case c < 0xF0:
				extra, cp = 2, rune(c&0x0F)
			default:
				extra, cp = 3, rune(c&0x07)
			}
			for i := 1; i <= extra; i++ {
				cp = cp<<6 | rune(in[p+i]&0x3F)
			}
			p += extra + 1
		}
		s = append(s, cp)
	}
	p++ // closing quote
	return s
}

func isDigit(i int) bool { return i < len(in) && in[i] >= '0' && in[i] <= '9' }

// parseNumber returns the exact decimal value without exponent, redundant zeros or a negative zero.
func parseNumber() string {
	negative := in[p] == '-'
	if negative {
		p++
	}
	var digits []byte
	exponent := 0
	for isDigit(p) {
		digits = append(digits, in[p])
		p++
	}
	if p < len(in) && in[p] == '.' {
		p++
		for isDigit(p) {
			digits = append(digits, in[p])
			p++
			exponent--
		}
	}
	if p < len(in) && (in[p] == 'e' || in[p] == 'E') {
		p++
		sign := 1
		if in[p] == '+' {
			p++
		} else if in[p] == '-' {
			sign = -1
			p++
		}
		e := 0
		for isDigit(p) {
			e = e*10 + int(in[p]-'0')
			p++
		}
		exponent += sign * e
	}
	// value = digits * 10^exponent
	d := strings.TrimLeft(string(digits), "0")
	if d == "" {
		return "0"
	}
	for d[len(d)-1] == '0' {
		d = d[:len(d)-1]
		exponent++
	}
	var text string
	switch {
	case exponent >= 0:
		text = d + strings.Repeat("0", exponent)
	case len(d) > -exponent:
		point := len(d) + exponent
		text = d[:point] + "." + d[point:]
	default:
		text = "0." + strings.Repeat("0", -exponent-len(d)) + d
	}
	if negative {
		return "-" + text
	}
	return text
}

func parseValue() *node {
	skipSpace()
	v := &node{}
	switch c := in[p]; c {
	case '{':
		v.kind = 'o'
		p++
		skipSpace()
		if in[p] == '}' {
			p++
			break
		}
		for {
			skipSpace()
			v.keys = append(v.keys, parseString())
			skipSpace()
			p++ // ':'
			v.values = append(v.values, parseValue())
			skipSpace()
			p++
			if in[p-1] == '}' {
				break
			}
		}
	case '[':
		v.kind = 'a'
		p++
		skipSpace()
		if in[p] == ']' {
			p++
			break
		}
		for {
			v.values = append(v.values, parseValue())
			skipSpace()
			p++
			if in[p-1] == ']' {
				break
			}
		}
	case '"':
		v.kind = 's'
		v.text = parseString()
	case 't':
		v.kind = 't'
		p += 4
	case 'f':
		v.kind = 'f'
		p += 5
	case 'n':
		v.kind = 'z'
		p += 4
	default:
		v.kind = 'n'
		v.number = parseNumber()
	}
	return v
}

// encodeString escapes like Python json.dumps(..., ensure_ascii=True).
func encodeString(s []rune, out *strings.Builder) {
	out.WriteByte('"')
	for _, c := range s {
		switch {
		case c == '"':
			out.WriteString(`\"`)
		case c == '\\':
			out.WriteString(`\\`)
		case c == '\n':
			out.WriteString(`\n`)
		case c == '\r':
			out.WriteString(`\r`)
		case c == '\t':
			out.WriteString(`\t`)
		case c == 8:
			out.WriteString(`\b`)
		case c == 12:
			out.WriteString(`\f`)
		case c >= 0x20 && c <= 0x7E:
			out.WriteByte(byte(c))
		case c > 0xFFFF:
			fmt.Fprintf(out, `\u%04x\u%04x`, 0xD800+(c-0x10000)>>10, 0xDC00+(c-0x10000)&0x3FF)
		default:
			fmt.Fprintf(out, `\u%04x`, c)
		}
	}
	out.WriteByte('"')
}

func encode(v *node, out *strings.Builder) {
	switch v.kind {
	case 'z':
		out.WriteString("null")
	case 't':
		out.WriteString("true")
	case 'f':
		out.WriteString("false")
	case 'n':
		out.WriteString(v.number)
	case 's':
		encodeString(v.text, out)
	case 'a':
		out.WriteByte('[')
		for i, item := range v.values {
			if i > 0 {
				out.WriteByte(',')
			}
			encode(item, out)
		}
		out.WriteByte(']')
	default:
		// Keys in ascending code point order.
		order := make([]int, len(v.keys))
		for i := range order {
			order[i] = i
		}
		slices.SortFunc(order, func(a, b int) int { return slices.Compare(v.keys[a], v.keys[b]) })
		out.WriteByte('{')
		for i, j := range order {
			if i > 0 {
				out.WriteByte(',')
			}
			encodeString(v.keys[j], out)
			out.WriteByte(':')
			encode(v.values[j], out)
		}
		out.WriteByte('}')
	}
}

func main() {
	in, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	cur := parseValue()
	skipSpace()
	path := parseString()
	// Split the path on '.', keeping empty segments, and walk object keys only.
	start := 0
	for i := 0; i <= len(path) && cur != nil; i++ {
		if i < len(path) && path[i] != '.' {
			continue
		}
		key := path[start:i]
		start = i + 1
		var next *node
		if cur.kind == 'o' {
			for j, k := range cur.keys {
				if slices.Equal(k, key) {
					next = cur.values[j]
					break
				}
			}
		}
		cur = next
	}
	var out strings.Builder
	if cur == nil {
		out.WriteString("null")
	} else {
		encode(cur, &out)
	}
	out.WriteByte('\n')
	os.Stdout.WriteString(out.String())
}
